  16: {
    id: "16",
    order: 16,
    articleNumber: 16,
    chapter: CH1,
    section: SEC_GEN,
    isAmended: false,
    officialText:
      "1. إذا لم يتمكن صاحب العمل من ممارسة العمل بنفسه، فعليه أن يعين مسؤولاً يمثله في مكان العمل. وفي حالة تعدد الشركاء أو المديرين في المنشأة يسمى أحدهم من المقيمين في مكان العمل، يمثل صاحب العمل ويكون مسؤولاً عن أي مخالفة لأحكام هذا النظام. 2. على صاحب العمل أن يبلغ مكتب العمل المختص كتابة باسم الشريك أو المدير، وعليه في حالة تغييره أن يبلغ المكتب بإسم الشريك أو المدير الجديد خلال سبعة أيام على الأكثر من تولي هذا الأخير عمله. 3. إذا لم يوجد شخص معين بصفة مدير مسؤول للمنشأة - او إذا لم يباشر الشخص المعين عمله – فإن من يقوم فعلاً بأعمال المدير أو صاحب العمل نفسه يعد مديراً مسؤولاً عن المنشأة. وفي كل الأحوال تبقى مسؤولية صاحب العمل قائمة بصفة أصلية.",
    originalText: null,
    amendmentInfo: null,
    simplifiedAr:
      "إذا لم يدِر صاحب العمل منشأته بنفسه، عليه تعيين مدير مسؤول يمثّله وإبلاغ مكتب العمل باسمه (وبأي تغيير خلال سبعة أيام). ومن يمارس عمل المدير فعلاً يُعد مسؤولاً، وتبقى مسؤولية صاحب العمل قائمة أصلاً في كل الأحوال.",
    example: {
      scenario: "يغيّر صاحب عمل مدير منشأته ولا يبلّغ مكتب العمل بالاسم الجديد.",
      outcome:
        "يخالف ذلك المادة التي توجب إبلاغ المكتب باسم المدير الجديد خلال سبعة أيام من توليه عمله.",
    },
    keywords: ["المدير المسؤول", "تمثيل صاحب العمل", "إبلاغ مكتب العمل"],
    relatedArticles: ["15", "13"],
    lastUpdated: "1426",
    status: "entered",
  },

